import React, { useState } from 'react';
import { useIntegrationLibrary } from './shared/useIntegrationLibrary';
import { formStyles } from './shared/IntegrationFormStyles';

/**
 * Dropbox Integration Component
 */
export default function Dropbox({ settings, hasPro, root, nonce, setMessage, isConnected, setShowDisconnectModal, setDisconnectIntegration }) {
  const { libraryInstalled, setLibraryInstalled, installing, installLibrary } = useIntegrationLibrary(
    'dropbox',
    root,
    nonce,
    hasPro
  );

  const [showAppSecret, setShowAppSecret] = useState(false);

  const handleInstallLibrary = async () => {
    const result = await installLibrary();
    if (result.success) {
      setMessage({ type: 'success', text: result.message });
      setTimeout(() => setMessage(null), 3000);
    } else {
      setMessage({ type: 'error', text: result.message });
      setTimeout(() => setMessage(null), 5000);
    }
  };

  // Update library installed status from settings
  React.useEffect(() => {
    if (settings.library_installed !== undefined) {
      setLibraryInstalled(settings.library_installed);
    }
  }, [settings.library_installed, setLibraryInstalled]);

  // Get redirect URI from settings or construct it
  const dropboxRedirectUri = settings.redirect_uri || 
    (window.location.protocol + '//' + window.location.host + '/wp-admin/admin.php?page=file_manager_advanced_ui');

  const fieldsDisabled = !hasPro || !libraryInstalled;

  return (
    <>
      {!libraryInstalled && (
        <div style={formStyles.warningBox}>
          <p style={formStyles.warningText}>
            Dropbox library is not installed. Please install the library first to configure authentication settings.
          </p>
          <button
            type="button"
            onClick={handleInstallLibrary}
            disabled={!hasPro || installing}
            style={{
              ...formStyles.installButton,
              background: installing ? '#ccc' : '#3F6972',
              cursor: !hasPro || installing ? 'not-allowed' : 'pointer',
            }}
          >
            {installing ? 'Installing Library...' : 'Install Dropbox Library'}
          </button>
        </div>
      )}

      {/* Alias */}
      <div>
        <label htmlFor="title" style={formStyles.label}>Alias</label>
        <input
          type="text"
          id="title"
          name="title"
          defaultValue={settings.title || 'Dropbox'}
          disabled={!hasPro}
          style={{ ...formStyles.input, maxWidth: '500px' }}
        />
        <p style={formStyles.description}>Enter a title which will be displayed on File Manager</p>
      </div>

      {/* App Key */}
      <div>
        <label htmlFor="app_key" style={formStyles.label}>App Key</label>
        <input
          type="text"
          id="app_key"
          name="app_key"
          defaultValue={settings.app_key || ''}
          disabled={!hasPro}
          style={{ ...formStyles.input, maxWidth: '500px' }}
        />
        <p style={formStyles.description}>
          Enter your Dropbox App key, you will get your app key from{' '}
          <a href="https://www.dropbox.com/developers/apps" target="_blank" rel="noopener noreferrer" style={formStyles.link}>
            Dropbox App Console
          </a>
        </p>
      </div>

      {/* App Secret */}
      <div>
        <label htmlFor="app_secret" style={formStyles.label}>App Secret</label>
        <div style={{ position: 'relative', maxWidth: '500px' }}>
          <input
            type={showAppSecret ? 'text' : 'password'}
            id="app_secret"
            name="app_secret"
            defaultValue={settings.app_secret || ''}
            disabled={!hasPro}
            style={formStyles.input}
          />
          <button
            type="button"
            onClick={() => setShowAppSecret(!showAppSecret)}
            style={{
              position: 'absolute',
              right: '10px',
              top: '50%',
              transform: 'translateY(-50%)',
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              padding: '5px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#666',
            }}
            title={showAppSecret ? 'Hide App Secret' : 'Show App Secret'}
          >
            {showAppSecret ? (
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"></path>
                <line x1="1" y1="1" x2="23" y2="23"></line>
              </svg>
            ) : (
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                <circle cx="12" cy="12" r="3"></circle>
              </svg>
            )}
          </button>
        </div>
        <p style={formStyles.description}>
          Enter your Dropbox App secret, you will get your app secret from{' '}
          <a href="https://www.dropbox.com/developers/apps" target="_blank" rel="noopener noreferrer" style={formStyles.link}>
            Dropbox App Console
          </a>
        </p>
      </div>

      {/* Redirect URI (Read-only) */}
      <div>
        <label htmlFor="redirect_uri" style={formStyles.label}>Redirect URI</label>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', maxWidth: '500px' }}>
          <input
            type="text"
            id="redirect_uri"
            name="redirect_uri"
            value={dropboxRedirectUri}
            readOnly
            disabled={!hasPro}
            style={{ ...formStyles.input, background: '#f5f5f5' }}
          />
          <button
            type="button"
            onClick={() => {
              navigator.clipboard.writeText(dropboxRedirectUri).then(() => {
                if (setMessage) {
                  setMessage({ type: 'success', text: 'Redirect URI copied to clipboard!' });
                  setTimeout(() => setMessage(null), 2000);
                }
              });
            }}
            disabled={!hasPro}
            style={{
              background: 'transparent',
              border: '1px solid #ddd',
              borderRadius: '4px',
              padding: '10px 12px',
              cursor: !hasPro ? 'not-allowed' : 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              opacity: !hasPro ? 0.5 : 1
            }}
            title="Copy to clipboard"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <rect x="9" y="9" width="13" height="13" rx="2" ry="2" stroke="#666" />
              <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" stroke="#666" />
            </svg>
          </button>
        </div>
        <p style={formStyles.description}>Copy this URL and paste it in your Dropbox App Console under Redirect URIs</p>
      </div>

      {/* Private Folder Access */}
      <div>
        <label htmlFor="private_folder_access" style={formStyles.label}>Private Folder Access</label>
        <input
          type="text"
          id="private_folder_access"
          name="private_folder_access"
          defaultValue={settings.private_folder_access || ''}
          disabled={fieldsDisabled}
          style={{ ...formStyles.input, maxWidth: '500px' }}
          placeholder="e.g. Documents"
        />
        <p style={formStyles.description}>
          Enter a folder name/path to restrict access to that folder only. Leave blank to use the root directory.
        </p>
      </div>

      {/* Connection Status and Button */}
      {libraryInstalled && (
        <div style={{ marginTop: '20px', paddingTop: '20px', borderTop: '1px solid #e5e5e5', position: 'relative', zIndex: 1001, maxWidth: '500px' }}>
          {isConnected ? (
            <div style={{ padding: '15px', background: '#d4edda', border: '1px solid #c3e6cb', borderRadius: '4px' }}>
              <p style={{ margin: '0 0 10px 0', color: '#155724', fontWeight: 600 }}>
                ✓ Connected to Dropbox
              </p>
              <button
                type="button"
                onClick={(e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  if (setDisconnectIntegration && setShowDisconnectModal) {
                    setDisconnectIntegration('dropbox');
                    setShowDisconnectModal(true);
                  }
                }}
                style={{
                  padding: '8px 16px',
                  background: '#dc3545',
                  color: '#fff',
                  border: 'none',
                  borderRadius: '4px',
                  fontSize: '14px',
                  fontWeight: 500,
                  cursor: 'pointer',
                }}
              >
                Disconnect Dropbox
              </button>
            </div>
          ) : (
            <>
              <p style={{ ...formStyles.description, marginBottom: '12px', color: '#dc2626', fontWeight: 600 }}>
                You are not connected with Dropbox
              </p>
              {settings.app_key && settings.app_secret ? (
                <a
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    
                    if (!settings.app_key || !settings.app_secret) {
                      alert('Please enter App key and App secret first, then save changes before connecting.');
                      return false;
                    }
                    
                    const redirectTo = window.location.hash || '#/extension/dropbox';
                    sessionStorage.setItem('afm-dropbox-redirect-to', redirectTo);
                    const state = redirectTo;
                    const connectUrl = `https://www.dropbox.com/oauth2/authorize?client_id=${encodeURIComponent(settings.app_key)}&response_type=code&token_access_type=offline&redirect_uri=${encodeURIComponent(dropboxRedirectUri)}&state=${encodeURIComponent(state)}`;
                    
                    window.location.href = connectUrl;
                    return false;
                  }}
                  style={{
                    display: 'inline-block',
                    padding: '10px 20px',
                    background: '#0061FF',
                    color: '#fff',
                    textDecoration: 'none',
                    borderRadius: '4px',
                    fontSize: '14px',
                    fontWeight: 600,
                    cursor: 'pointer',
                    border: 'none'
                  }}
                >
                  Connect Dropbox
                </a>
              ) : (
                <p style={{ ...formStyles.description, color: '#dc2626' }}>
                  Please enter your App key and App secret first, then save changes before connecting.
                </p>
              )}
            </>
          )}
        </div>
      )}
    </>
  );
}

