import React, { useState } from 'react';
import { formStyles } from './shared/IntegrationFormStyles';

/**
 * Google Drive Integration Component
 */
export default function GoogleDrive({
  settings,
  hasPro,
  isConnected,
  setShowDisconnectModal,
  setDisconnectIntegration,
  setMessage,
}) {
  const [showAppSecret, setShowAppSecret] = useState(false);
  const defaultRedirectUri = settings.redirect_uri || (window.location.origin + '/wp-admin/admin.php?page=file_manager_advanced_ui');

  return (
    <>
      {/* Alias */}
      <div>
        <label htmlFor="title" style={formStyles.label}>Alias</label>
        <input
          type="text"
          id="title"
          name="title"
          defaultValue={settings.title || 'Google Drive'}
          disabled={!hasPro}
          style={{ ...formStyles.input, maxWidth: '500px' }}
        />
        <p style={formStyles.description}>Enter a title which will be displayed on File Manager</p>
      </div>

      {/* App Key */}
      <div>
        <label htmlFor="app_key" style={formStyles.label}>App Key</label>
        <input
          type="text"
          id="app_key"
          name="app_key"
          defaultValue={settings.app_key || ''}
          disabled={!hasPro}
          style={{ ...formStyles.input, maxWidth: '500px' }}
        />
        <p style={formStyles.description}>
          Enter your Google Drive App key, you will get your app key from{' '}
          <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener noreferrer" style={formStyles.link}>
            Google Drive App Console
          </a>
        </p>
      </div>

      {/* App Secret */}
      <div>
        <label htmlFor="app_secret" style={formStyles.label}>App Secret</label>
        <div style={{ position: 'relative', maxWidth: '500px' }}>
          <input
            type={showAppSecret ? 'text' : 'password'}
            id="app_secret"
            name="app_secret"
            defaultValue={settings.app_secret || ''}
            disabled={!hasPro}
            style={formStyles.input}
          />
          <button
            type="button"
            onClick={() => setShowAppSecret(!showAppSecret)}
            style={{
              position: 'absolute',
              right: '10px',
              top: '50%',
              transform: 'translateY(-50%)',
              background: 'none',
              border: 'none',
              cursor: 'pointer',
              padding: '5px',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              color: '#666',
            }}
            title={showAppSecret ? 'Hide App Secret' : 'Show App Secret'}
          >
            {showAppSecret ? (
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"></path>
                <line x1="1" y1="1" x2="23" y2="23"></line>
              </svg>
            ) : (
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"></path>
                <circle cx="12" cy="12" r="3"></circle>
              </svg>
            )}
          </button>
        </div>
        <p style={formStyles.description}>
          Enter your Google Drive App secret, you will get your app secret from{' '}
          <a href="https://console.cloud.google.com/apis/credentials" target="_blank" rel="noopener noreferrer" style={formStyles.link}>
            Google Drive App Console
          </a>
        </p>
      </div>

      {/* JavaScript Origin */}
      <div>
        <label htmlFor="javascript_origin" style={formStyles.label}>Javascript Origin</label>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', maxWidth: '500px' }}>
          <input
            type="text"
            id="javascript_origin"
            name="javascript_origin"
            value={window.location.origin}
            readOnly
            disabled={!hasPro}
            style={{ ...formStyles.input, background: '#f5f5f5', cursor: 'not-allowed', maxWidth: '500px' }}
          />
          <button
            type="button"
            onClick={() => {
              navigator.clipboard.writeText(window.location.origin).then(() => {
                if (setMessage) {
                  setMessage({ type: 'success', text: 'JavaScript Origin copied to clipboard!' });
                  setTimeout(() => setMessage(null), 2000);
                }
              });
            }}
            disabled={!hasPro}
            style={{
              background: 'transparent',
              border: '1px solid #ddd',
              borderRadius: '4px',
              padding: '10px 12px',
              cursor: !hasPro ? 'not-allowed' : 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              opacity: !hasPro ? 0.5 : 1
            }}
            title="Copy to clipboard"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <rect x="9" y="9" width="13" height="13" rx="2" ry="2" stroke="#666" />
              <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" stroke="#666" />
            </svg>
          </button>
        </div>
        <p style={formStyles.description}>Copy this URL and paste it in your Google Drive App Console under JavaScript Origins</p>
      </div>

      {/* Redirect URL */}
      <div>
        <label htmlFor="redirect_uri" style={formStyles.label}>Redirect URL</label>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px', maxWidth: '500px' }}>
          <input
            type="text"
            id="redirect_uri"
            name="redirect_uri"
            value={defaultRedirectUri}
            readOnly
            disabled={!hasPro}
            style={{ ...formStyles.input, background: '#f5f5f5', cursor: 'not-allowed', maxWidth: '500px' }}
          />
          <button
            type="button"
            onClick={() => {
              navigator.clipboard.writeText(defaultRedirectUri).then(() => {
                if (setMessage) {
                  setMessage({ type: 'success', text: 'Redirect URL copied to clipboard!' });
                  setTimeout(() => setMessage(null), 2000);
                }
              });
            }}
            disabled={!hasPro}
            style={{
              background: 'transparent',
              border: '1px solid #ddd',
              borderRadius: '4px',
              padding: '10px 12px',
              cursor: !hasPro ? 'not-allowed' : 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              opacity: !hasPro ? 0.5 : 1
            }}
            title="Copy to clipboard"
          >
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <rect x="9" y="9" width="13" height="13" rx="2" ry="2" stroke="#666" />
              <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1" stroke="#666" />
            </svg>
          </button>
        </div>
        <p style={formStyles.description}>Copy this URL and paste it in your Google Drive App Console under Redirect URIs</p>
      </div>

      {/* Private Folder Access */}
      <div>
        <label htmlFor="private_folder_access" style={formStyles.label}>Private Folder Access</label>
        <input
          type="text"
          id="private_folder_access"
          name="private_folder_access"
          defaultValue={settings.private_folder_access || ''}
          disabled={!hasPro}
          style={{ ...formStyles.input, maxWidth: '500px' }}
          placeholder="e.g. Documents"
        />
        <p style={formStyles.description}>
          Enter a folder path to restrict access to that folder only. Leave blank to use the root directory.
        </p>
      </div>

      {/* Connection Status and Button */}
      <div style={{ marginTop: '20px', paddingTop: '20px', borderTop: '1px solid #e5e5e5', position: 'relative', zIndex: 1001 }}>
        {isConnected ? (
          <>
            <p style={{ ...formStyles.description, marginBottom: '12px', color: '#22c55e', fontWeight: 600 }}>
              ✓ You are connected with Google Drive
            </p>
            <button
              type="button"
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                if (setDisconnectIntegration && setShowDisconnectModal) {
                  setDisconnectIntegration('google-drive');
                  setShowDisconnectModal(true);
                }
              }}
              disabled={!hasPro}
              style={{
                display: 'inline-block',
                padding: '10px 20px',
                background: '#dc2626',
                color: '#fff',
                textDecoration: 'none',
                borderRadius: '4px',
                fontSize: '14px',
                fontWeight: 600,
                cursor: !hasPro ? 'not-allowed' : 'pointer',
                border: 'none',
                position: 'relative',
                zIndex: 1001,
                opacity: !hasPro ? 0.5 : 1,
              }}
            >
              Disconnect Google Drive
            </button>
          </>
        ) : (
          <>
            <p style={{ ...formStyles.description, marginBottom: '12px', color: '#dc2626', fontWeight: 600 }}>
              You are not connected with Google Drive
            </p>
            {settings.app_key && settings.app_secret ? (
              <a
                href={`https://accounts.google.com/o/oauth2/v2/auth?client_id=${encodeURIComponent(settings.app_key)}&response_type=code&redirect_uri=${encodeURIComponent(defaultRedirectUri)}&scope=https://www.googleapis.com/auth/drive&access_type=offline&prompt=consent&state=${encodeURIComponent(window.location.hash || '#/extension/google-drive')}`}
                style={{
                  display: 'inline-block',
                  padding: '10px 20px',
                  background: '#4285F4',
                  color: '#fff',
                  textDecoration: 'none',
                  borderRadius: '4px',
                  fontSize: '14px',
                  fontWeight: 600,
                  cursor: 'pointer',
                  border: 'none'
                }}
              >
                Connect Google Drive
              </a>
            ) : (
              <p style={{ ...formStyles.description, color: '#dc2626' }}>
                Please enter your App key and App secret first, then save changes before connecting.
              </p>
            )}
          </>
        )}
      </div>
    </>
  );
}
